using System.IO;
using System.Text.Json;
namespace PvZSymbiosisTranslator.UI;
public static class ModLabels
{
    private static readonly Dictionary<string,string> Overrides=new(StringComparer.Ordinal);
    public static Dictionary<string,string> LoadCandidate(string localeDirectory,Action<string> warning=null) {
        var next=new Dictionary<string,string>(StringComparer.Ordinal);var path=Path.Combine(localeDirectory,"ModStrings.json");
        if(!File.Exists(path)) path=Path.Combine(localeDirectory,"mod_ui.json");
        if(!File.Exists(path)) throw new FileNotFoundException("Required ModStrings file missing",path);
        using(var doc=Localization.JsonFile.Read(path,warning)) {
            if(doc.RootElement.ValueKind!=JsonValueKind.Object) throw new FormatException("ModStrings must be a JSON object");
            foreach(var item in doc.RootElement.EnumerateObject()) {
                if(item.Value.ValueKind!=JsonValueKind.String || string.IsNullOrWhiteSpace(item.Value.GetString())) throw new FormatException("Empty/non-string ModStrings value: "+item.Name);
                if(!next.TryAdd(item.Name,item.Value.GetString())) throw new FormatException("Duplicate ModStrings key: "+item.Name);
            }
        }
        var template=Path.Combine(Directory.GetParent(localeDirectory)?.FullName ?? "","_template","ModStrings.json");
        if(File.Exists(template)) using(var canonical=Localization.JsonFile.Read(template,warning)) {
            foreach(var item in canonical.RootElement.EnumerateObject()) if(!next.ContainsKey(item.Name)) throw new FormatException("Missing ModStrings key: "+item.Name);
        }
        return next;
    }
    public static void Apply(IReadOnlyDictionary<string,string> candidate) {
        if(candidate==null) throw new ArgumentNullException(nameof(candidate));
        Overrides.Clear();foreach(var item in candidate) Overrides.Add(item.Key,item.Value);
    }
    public static void Load(string localeDirectory) {
        Apply(LoadCandidate(localeDirectory));
    }
