    public static string Get(string locale,string key) =>
        (Overrides.TryGetValue(key,out var custom) || Overrides.TryGetValue("mod."+key,out custom) || Overrides.TryGetValue("mod.settings."+key,out custom)) ? custom :
        locale == "pt-BR" && Portuguese.TryGetValue(key,out var text) ? text : English.TryGetValue(key,out text) ? text : key;
}
